import type { GuideContent } from '../types';
import { parseAmount, toWords, type Amount, type Lang, type WordsOptions } from '../../tools/words/engine.ts';

// Every amount in words below is generated by the engine, so the text always matches the tool.
const say = (lang: Lang, n: string, o: Partial<WordsOptions>) =>
  toWords(lang, parseAmount(n, o.currency === 'KWD') as Amount, { currency: '', ...o });

const P = '2026-09-27';

